import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE u (id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE)');
  db.exec("INSERT INTO u (email) VALUES ('a@x')");
  try { db.exec("INSERT INTO u (email) VALUES ('a@x')"); } catch (e: any) { console.log(e.code, e.errcode, e.errstr, e.message); }
  try { db.exec('INSERT INTO u (email) VALUES (NULL)'); } catch (e: any) { console.log(e.code, e.errcode, e.errstr, e.message); }
  try { db.prepare('SELEC 1'); } catch (e: any) { console.log(e.code, e.errcode, e.errstr, e.message); }
  db.close();
}
